PREFIX prov:  <http://www.w3.org/ns/prov#>
PREFIX xsd:   <http://www.w3.org/2001/XMLSchema#>

select distinct ?entity ?class ?start ?end
where {
  ?entity a <{{this.nodeType}}> ;
          prov:startedAtTime ?start ;
          prov:endedAtTime   ?end .

  BIND(IF(DATATYPE(?start)=xsd:dateTime, ?start, xsd:dateTime(STR(?start))) AS ?startDT)
  BIND(IF(DATATYPE(?end)  =xsd:dateTime, ?end,   xsd:dateTime(STR(?end)))   AS ?endDT)

  FILTER(
      ?endDT >= "{{this.startDate}}"^^xsd:dateTime && ?startDT <= "{{this.endDate}}"^^xsd:dateTime
  )
}
ORDER BY ?start
LIMIT 200

select distinct ?result ?hop ?via1 ?via2 ?resultLabel
where {
  # Resolve the start node from an ID property/value
  ?start ?idProp "{{this.nodeID}}" .

  {
    # 1 hop
    ?start ?via1 ?result .
    bind(1 AS ?hop)
  }
  union
  {
    # 2 hops
    ?start ?via1 ?mid .
    ?mid   ?via2 ?result .
    bind(2 AS ?hop)
  }

  ?result a <{{this.targetType}}> .

  optional { ?result rdfs:label ?resultLabel }
}

select distinct ?s ?p ?o 
	where {
    	{?s ?p ?o .
    	filter (?s = <{{this.node}}>)
    }
    union
    {
       ?s ?p ?o .
    	filter (?o = <{{this.node}}>) 
    }
} 
limit 100

