// Create ramp from min -> max over an 8 hour shift
function getRampValue(min, max, offset){
  let shiftHours = Math.abs((new Date().getHours() - offset) % 8)
  let shiftMinutes = new Date().getMinutes()
  let totalMinutes = shiftHours * 60 + shiftMinutes

  let minutesMax = 8 * 60
  let minutesPerct = totalMinutes/minutesMax

  return (minutesPerct * (max - min))
}

/*
Code to simulate the crusher machine. Shift 2 increases the feed rate and causes issues.
The simulation is based on time. The data is generated for the time the function is called.
*/
const CrusherSimulator = (() => {
  function fluctuate(value, amount) {
    return value + (Math.random() * amount * 2 - amount);
  }

  function rampedSineWave(baseValue, amplitude, frequency, time, rampRate) {
    return baseValue + (time * rampRate) + amplitude * Math.sin(frequency * time) + fluctuate(0, 0.5);
  }

  function getNormalCrusherValues() {
    return {
      feedRate: fluctuate(8, 0.5),
      vibration: fluctuate(29, 1),
      temperature: fluctuate(87, 2),
      power: fluctuate(69, 3),
      crushRate: fluctuate(9, 0.2),
      rpm: fluctuate(980, 5)
    };
  }

  function getShiftTwoCrusherValues(secondsIntoShift) {
    const feedRateBase = 12 + (secondsIntoShift / 28800) * 4; // Ramp feed rate from 12 to 16
    const feedRate = fluctuate(feedRateBase, 0.5);
    const vibration = rampedSineWave(40, 2, 0.05, secondsIntoShift / 60, 0.02);
    const power = rampedSineWave(85, 5, 0.05, secondsIntoShift / 60, 0.03);
    const temperature = fluctuate(95, 1);
    const crushRateBase = 9 - (secondsIntoShift / 28800) * 1;
    const crushRate = fluctuate(crushRateBase, 0.2);
    const rpm = fluctuate(980, 5);

    return { feedRate, vibration, temperature, power, crushRate, rpm };
  }

  function getErrorCrusherValues() {
    return {
      feedRate: fluctuate(16, 0.5),            // very high feed rate
      vibration: fluctuate(60, 5),             // extremely high vibration
      temperature: fluctuate(120, 3),          // overheat
      power: fluctuate(95, 4),                 // higher power draw
      crushRate: fluctuate(5, 0.2),            // low output
      rpm: fluctuate(970, 3)                   // slight drop in RPM
    };
  }

  function getShiftAndSecond(hour, minute, second) {
    const shift = Math.floor(hour / 8) + 1;
    const secondsWithinShift = ((hour % 8) * 3600) + (minute * 60) + second;
    return { shift, secondsWithinShift };
  }

  function simulateCrusher(hour, minute, second, mode = "auto") {
    const { shift, secondsWithinShift } = getShiftAndSecond(hour, minute, second);

    let crusherValues;
    if (mode === "error") {
      crusherValues = getErrorCrusherValues();
    } else if (mode === "normal") {
      crusherValues = getNormalCrusherValues();
    } else {
      crusherValues = (shift === 2)
        ? getShiftTwoCrusherValues(secondsWithinShift)
        : getNormalCrusherValues();
    }

    const now = new Date();
    const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
    const simulatedTime = new Date(yesterday.getFullYear(), yesterday.getMonth(), yesterday.getDate(), hour, minute, second);
    const timestamp = Math.floor(simulatedTime.getTime() / 1000);

    return {
      timestamp,
      shift,
      feedRate: crusherValues.feedRate,
      vibration: crusherValues.vibration,
      temperature: crusherValues.temperature,
      power: crusherValues.power,
      crushRate: crusherValues.crushRate,
      rpm: crusherValues.rpm
    };
  }

  function simulateFullDayToCSV() {
    const csvRows = [
      "_timestamp,shift,feedRate,vibration,temperature,powerKW,crushRate,rpm,_path"
    ];

    const now = new Date();
    const yesterday = new Date(now.setDate(now.getDate() - 1));
    yesterday.setHours(0, 0, 0, 0);
    const baseEpoch = yesterday.getTime();

    for (let secondsIntoDay = 0; secondsIntoDay < 86400; secondsIntoDay++) {
      const timestamp = baseEpoch + secondsIntoDay * 1000;
      const hour = Math.floor(secondsIntoDay / 3600);
      const minute = Math.floor((secondsIntoDay % 3600) / 60);
      const second = secondsIntoDay % 60;

      const data = simulateCrusher(hour, minute, second);
      data.timestamp = timestamp;

      const csvRow = `${data.timestamp},${data.shift},${data.feedRate},${data.vibration},${data.temperature},${data.power},${data.crushRate},${data.rpm},"Portland/Line1"`;
      csvRows.push(csvRow);
    }

    const csvContent = csvRows.join("\n");
    fs.writeFileSync("data/crusher_simulation_yesterday.csv", csvContent, "utf8");
    console.log("CSV file created for crusher simulation over a full day.");
  }

  function simulateNow(mode = "auto") {
    const now = new Date();
    const hour = now.getHours();
    const minute = now.getMinutes();
    const second = now.getSeconds();

    return simulateCrusher(hour, minute, second, mode);
  }

  return {
    simulateFullDayToCSV,
    simulateNow
  };
})();

// PackerSimulator to encapsulate the packer simulation logic
const PackerSimulator = (() => {
  // Function to reset packer state at the start of each shift
  const resetPackerState = () => ({
    fillWeight: 116,
    bagsPerMinute: 3,
    bagCount: 0,
    packagingSupply: 2000,
    goodSeals: 0,
    badSeals: 0,
    power: 58,
    status: true
  });

  // Plant configurations for different fill weight targets and bag rates
  const plants = {
    highFill: { fillWeightTarget: 120, bagRate: 3, _path:  'Boston/Line1'},
    lowFill: { fillWeightTarget: 112, bagRate: 4, _path:  'Albany/Line1' },
    idealFill: { fillWeightTarget: 116, bagRate: 3, _path: 'Portland/Line1' }
  };

  // Store the state of each plant across shifts
  let packerState = {
    highFill: resetPackerState(),
    lowFill: resetPackerState(),
    idealFill: resetPackerState()
  };

  // Function to simulate the packer machine at a specific plant and specific minute of the day
  function simulatePacker(plantName, hour, minute) {
    // Determine the shift and minute within the shift
    const { shift, minuteWithinShift } = getShiftAndMinute(hour, minute);

    // Reset the packer state at the start of each shift
    if (minute === 0 && hour % 8 === 0) {
      packerState = {
        highFill: resetPackerState(),
        lowFill: resetPackerState(),
        idealFill: resetPackerState()
      };
    }

    const plantState = getPackerValues(plantName, minuteWithinShift);

    // Calculate the epoch timestamp for the specific simulated time on yesterday's date
    const now = new Date();
    const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
    const simulatedTime = new Date(yesterday.getFullYear(), yesterday.getMonth(), yesterday.getDate(), hour, minute);
    const timestamp = Math.floor(simulatedTime.getTime() / 1000); // Convert to epoch time in seconds

    return {
      timestamp,
      shift,
      plant: plantName,
      fillWeight: plantState.fillWeight.toFixed(2),
      bagsPerMinute: plantState.bagsPerMinute,
      bagCount: plantState.bagCount,
      goodSeals: plantState.goodSeals,
      badSeals: plantState.badSeals,
      power: plantState.power,
      packagingSupply: plantState.packagingSupply,
      status: plantState.status,
	  _path: plants[plantName]._path,
    };
  }

  // Helper function to calculate shift and minute within the shift
  function getShiftAndMinute(hour, minute) {
    const shift = Math.floor(hour / 8) + 1; // 3 shifts per day (8 hours each)
    const minuteWithinShift = (hour % 8) * 60 + minute;
    return { shift, minuteWithinShift };
  }

  // Function to determine packer values based on the current plant and minute within shift
  function getPackerValues(plantName, minutesIntoShift) {
    const plantConfig = plants[plantName];

    const fillWeight = plantConfig.fillWeightTarget
    let bagsPerMinute = plantConfig.bagRate

    // Round bags per minute to a whole number
    bagsPerMinute = Math.round(bagsPerMinute);

    // Define bad seal rates for each plant
    let badSealRate = 0.01; // 1% for ideal fill weight
    if (plantName === 'highFill') {
      badSealRate = 0.20; // 20% for high fill weight
    } else if (plantName === 'lowFill') {
      badSealRate = 0.10; // 10% for low fill weight
    }

    // Calculate the number of bags produced this minute
    const totalBagsThisMinute = Math.max(1, bagsPerMinute); // Ensure at least one bag is produced

    // Update the state for bagCount and packagingSupply
    packerState[plantName].bagCount += totalBagsThisMinute; // Increment by bags produced this minute
    packerState[plantName].packagingSupply = Math.max(0, packerState[plantName].packagingSupply - totalBagsThisMinute); // Decrease packaging supply
    packerState[plantName].badSeals = Math.floor(packerState[plantName].bagCount * badSealRate);
	packerState[plantName].goodSeals = packerState[plantName].bagCount - packerState[plantName].badSeals

    return {
      fillWeight,
      bagsPerMinute,
      bagCount: packerState[plantName].bagCount,
      goodSeals: packerState[plantName].goodSeals,
      badSeals: packerState[plantName].badSeals,
      power: packerState[plantName].power,
      packagingSupply: packerState[plantName].packagingSupply,
      status: packerState[plantName].status,
    };
  }

  // Function to simulate data for a full day (all plants) and save it to CSV
  function simulateFullDayToCSV() {
    const csvRows = [
      "_timestamp,shift,plant,fillWeight,bagsPerMinute,bagCount,goodSeals,badSeals,power,packagingSupply,status,_path" // CSV header
    ];

    // Set the base time as the start of "yesterday"
    const now = new Date();
    const yesterday = new Date(now.setDate(now.getDate() - 1));
    yesterday.setHours(0, 0, 0, 0); // Set to 00:00:00 of the previous day
    const baseEpoch = yesterday.getTime();

    // Simulate data for a continuous 24-hour period, once per minute
    for (let minutesIntoDay = 0; minutesIntoDay < 1440; minutesIntoDay++) {
      const timestamp = baseEpoch + minutesIntoDay * 60 * 1000;
      const hour = Math.floor(minutesIntoDay / 60);
      const minute = minutesIntoDay % 60;

      // Simulate data for each plant (highFill, lowFill, idealFill)
      for (const plantName of Object.keys(plants)) {
        const data = simulatePacker(plantName, hour, minute);
        data.timestamp = timestamp;

        // Format the data into CSV row format
        const csvRow = `${data.timestamp},${data.shift},${data.plant},${data.fillWeight},${data.bagsPerMinute},${data.bagCount},${data.goodSeals},${data.badSeals},${data.power},${data.packagingSupply},${data.status},${data._path}`;
        csvRows.push(csvRow);
      }
    }

    // Join all rows by newline and write to file in the 'data' folder
    const csvContent = csvRows.join("\n");
    const outputPath = "data/packer_simulation_yesterday.csv";
    fs.writeFileSync(outputPath, csvContent, "utf8");
    console.log("CSV file created for packer simulation over a full day: " + outputPath);
  }
  
  // Simulate data for this point in time, on a simulated 3 day shift
  function simulateNow(plantName) {
    const now = new Date();
    const hour = now.getHours();
    const minute = now.getMinutes();

    // Generate simulation for the current hour and minute
    return (simulatePacker(plantName, hour, minute))
  }

  return {
    simulateFullDayToCSV,
	  simulateNow
  };
})();

// String(XML) -> Object
// Function to parse XML string into JSON
function xmlToJson(xmlString) { 
    const json = {}; 
    const rows = []; 
    //xmlString = xmlString.replace(/<\?xml.*?\?>|<!--.*?-->/g, '');
    // Extract <Row> elements from the XML string 
    const rowMatches = xmlString.match(/<Row[^>]*\/>/gm); 

    if (!rowMatches) return json; 

    // Iterate over each <Row> element 
    rowMatches.forEach(rowMatch => { 
        const row = {}; 
        // Extract attributes from the <Row> element using regular expressions 
        const attributeMatches = rowMatch.match(/\b(\w+)="([^"]*)"/g); 
        attributeMatches.forEach(attributeMatch => { 
            const [key, value] = attributeMatch.split('='); 
            row[key] = value.replace(/"/g, ''); // Remove double quotes from attribute values 
        }); 
        rows.push(row); 
    }); 

    // Add the rows array to the JSON object 
    json["root"] = { "value": rows }; 

    return json; 
}

