// Object (String -> Boolean) -> Object
// Abstract function to filter a given Object
function objectFilter(predicate,obj) {
    Object.filter = (obj, predicate) =>
        Object.keys(obj)
            .filter( key => predicate(key))
            .reduce( (res, key) => (res[key] = obj[key], res), {} );
    return Object.filter(obj, predicate);
}

