// Produce a string that indicates whether the given string is a float, integer, or a string
function checkStringType(s) {
    const floatValue = parseFloat(s);
    if (!isNaN(floatValue) && /^\d*\.?\d*$/.test(s.trim())) {
        return "float"
    }
    const intValue = parseInt(s,10)
    if (!isNaN(intValue) && /^\d+$/.test(s.trim())) {
        return "integer"
    }
    return "string"
}

function linspace(start, stop, num) {
  const arr = [];
  const step = (stop - start) / (num - 1);

  for (let i = 0; i < num; i++) {
    arr.push(start + step * i);
  }

  return arr;
}

function parseEvtString(evtString) {
    // Normalize line endings
    const normalized = evtString.replace(/\r\n/g, '\n').trim();

    // Split lines
    const lines = normalized.split('\n');

    // Extract headers
    const headers = lines[0].split('\t');

    // Parse each line into an object
    const records = lines.slice(1).map(line => {
        const fields = line.split('\t');
        const record = {};
        headers.forEach((header, index) => {
            record[header] = fields[index] || "";  // default to empty string if missing
        });
        return record;
    });

    return records;
}

function nestEvents(events) {
  const tree = {};

  events.forEach(event => {
    const {
      BatchID,
      Recipe,
      GMTtime,
      PValue
    } = event;

    if (!BatchID) return;

    // Ensure batch exists
    if (!tree[BatchID]) {
      tree[BatchID] = {
        startTime: null,
        endTime: null,
        Area: null,
        Unit: null,
        ProcCell: null,
        Recipe: null,
        Descript: null,
        Event: null,
        PValue: null,
        EU: null,
        Phase: null,
        PhaseDesc: null,
        UserID: null,
        UniqueID: null,
        Comment: null,
        ParamDesc: null,
        children: {}
      };
    }

    const batchNode = tree[BatchID];

    // Set batch-level startTime and metadata
    if (PValue === "CREATED" && !batchNode.startTime) {
      batchNode.startTime = GMTtime;
      Object.keys(event).forEach(key => {
        if (key !== "GMTtime" && batchNode[key] === null) {
          batchNode[key] = event[key];
        }
      });
      batchNode.PValue = event.PValue;
    }

    // Set batch-level endTime and metadata (without overwriting existing)
    if (PValue === "REMOVED" && !batchNode.endTime) {
      batchNode.endTime = GMTtime;
      Object.keys(event).forEach(key => {
        if (key !== "GMTtime" && batchNode[key] === null) {
          batchNode[key] = event[key];
        }
      });
      batchNode.PValue = event.PValue;
    }

    // Now continue as usual with nested structure (if Recipe is valid)
    if (!Recipe) return;
    const levels = Recipe.split("\\\\").filter(Boolean);

    let currentLevel = batchNode.children;
    let node = null;

    levels.forEach((levelName, index) => {
      const isDeepestLevel = index === levels.length - 1;

      if (!currentLevel[levelName]) {
        currentLevel[levelName] = {
          startTime: null,
          endTime: null,
          ...(isDeepestLevel ? { events: {}, eventCounter: 0 } : {}),
          Area: null,
          Unit: null,
          ProcCell: null,
          Recipe: null,
          Descript: null,
          Event: null,
          PValue: null,
          EU: null,
          Phase: null,
          PhaseDesc: null,
          UserID: null,
          UniqueID: null,
          Comment: null,
          ParamDesc: null,
          children: {}
        };
      }

      node = currentLevel[levelName];
      currentLevel = node.children;
    });

    if (PValue === "RUNNING" && !node.startTime) {
      node.startTime = GMTtime;
      Object.keys(event).forEach(key => {
        if (key !== "GMTtime" && node[key] === null) {
          node[key] = event[key];
        }
      });
      if (!node.endTime) node.PValue = event.PValue;
    }

    if (
      ["COMPLETE", "STOPPED", "ABORTED"].includes(PValue) &&
      !node.endTime
    ) {
      node.endTime = GMTtime;
      Object.keys(event).forEach(key => {
        if (key !== "GMTtime" && node[key] === null) {
          node[key] = event[key];
        }
      });
      node.PValue = event.PValue;
    }

    if (node?.events) {
      node.eventCounter += 1;
      node.events[node.eventCounter] = event;
    }
  });

  function clean(node) {
    delete node.eventCounter;
    for (const key in node.children) {
      clean(node.children[key]);
    }
  }

  for (const batch in tree) {
    clean(tree[batch]);
  }

  return tree;
}

function tagLevels(tree) {
  function classify(node) {
    if (!node.children || Object.keys(node.children).length === 0) {
      node._level = "Phase";
      return "Phase";
    }

    const childLevels = new Set(
      Object.values(node.children).map(classify)
    );

    if (childLevels.size === 1) {
      const only = [...childLevels][0];
      const nextLevel = {
        Phase: "Operation",
        Operation: "UnitProcedure",
        UnitProcedure: "Procedure"
      }[only];

      if (nextLevel) {
        node._level = nextLevel;
        return nextLevel;
      }
    }

    node._level = "Unknown";
    return "Unknown";
  }

  for (const batchID in tree) {
    classify(tree[batchID]);
  }

  return tree;
}


function transformToDeterministicFormat(nestedTree) {
  const deterministic = { Record: {} };
  let recordCounter = 1;

  // Maps singular levels to plural container keys
  const pluralMap = {
    Procedure: 'Procedures',
    UnitProcedure: 'UnitProcedures',
    Operation: 'Operations',
    Phase: 'Phases'
  };

  function transformLevel(node) {
    const result = {};
    let childCounter = 1;

    for (const name in node.children) {
      const child = node.children[name];
      const transformed = {
        Name: name,
        startTime: child.startTime,
        endTime: child.endTime,
        Area: child.Area,
        Unit: child.Unit,
        ProcCell: child.ProcCell,
        Recipe: child.Recipe,
        Descript: child.Descript,
        Event: child.Event,
        PValue: child.PValue,
        EU: child.EU,
        Phase: child.Phase,
        PhaseDesc: child.PhaseDesc,
        UserID: child.UserID,
        UniqueID: child.UniqueID,
        Comment: child.Comment,
        ParamDesc: child.ParamDesc
      };

      if (child.events) {
        transformed.events = child.events;
      }

      if (child.children && Object.keys(child.children).length > 0) {
        const nextLevelType = Object.values(child.children)[0]._level;
        const nextLevelKey = pluralMap[nextLevelType] || 'Nested';
        transformed[nextLevelKey] = transformLevel(child);
      }

      result[String(childCounter++)] = transformed;
    }

    return result;
  }

  for (const batchID in nestedTree) {
    const batchNode = nestedTree[batchID];
    const recordKey = String(recordCounter++);

    deterministic.Record[recordKey] = {
      BatchID: batchID,
      startTime: batchNode.startTime,
      endTime: batchNode.endTime,
      Area: batchNode.Area,
      Unit: batchNode.Unit,
      ProcCell: batchNode.ProcCell,
      Recipe: batchNode.Recipe,
      Descript: batchNode.Descript,
      Event: batchNode.Event,
      PValue: batchNode.PValue,
      EU: batchNode.EU,
      Phase: batchNode.Phase,
      PhaseDesc: batchNode.PhaseDesc,
      UserID: batchNode.UserID,
      UniqueID: batchNode.UniqueID,
      Comment: batchNode.Comment,
      ParamDesc: batchNode.ParamDesc
    };

    if (batchNode.children && Object.keys(batchNode.children).length > 0) {
      const nextLevelType = Object.values(batchNode.children)[0]._level;
      const nextLevelKey = pluralMap[nextLevelType] || 'Nested';
      deterministic.Record[recordKey][nextLevelKey] = transformLevel(batchNode);
    }
  }

  return deterministic;
}

function getLatestEvtRegex(files) {
    if (!Array.isArray(files)) return null;

    // Filter to .evt files only
    const evtFiles = files.filter(file => typeof file.name === 'string' && file.name.endsWith(".evt"));
    if (evtFiles.length === 0) return null;

    // Find the latest .evt file
    const latestFile = evtFiles.reduce((latest, current) =>
        new Date(current.updateTime) > new Date(latest.updateTime) ? current : latest
    );

    // Escape special regex characters in filename
    const escapedName = latestFile.name.replace(/[-[\]/{}()*+?.\\^$|]/g, '\\$&');

    // Return regex pattern string to match that filename exactly
    return `^${escapedName}$`;
}
